abhinav_29_32 = {
    'hi': '।।6.29--6.32।। श्री अभिनवगुप्त कहते हैं: योग में युक्त अन्तःकरण वाला सर्वत्र समदृष्टि योगी सब भूतों में अपने आत्मा को और अपने आत्मा में सब भूतों को देखता है। जो मुझे सब में देखता है और सब को मुझमें देखता है, उसके लिए मैं अदृश्य नहीं होता और वह मेरे लिए अदृश्य नहीं होता। जो योगी एकीभाव में स्थित होकर सर्व भूतों में स्थित मुझे भजता है, वह सब प्रकार से वर्तमान रहता हुआ भी मुझमें ही वर्तता है। हे अर्जुन ! जो अपनी उपमा से सब भूतों में सुख या दुःख को समान देखता है, वह परम योगी माना गया है।',
    'en': '6.29--6.32 Sri Abhinavagupta states: He whose heart is harmonized by Yoga sees the Self abiding in all beings and all beings abiding in the Self, beholding the same everywhere. He who sees Me everywhere and sees all in Me, to him I am never lost, nor is he ever lost to Me. The Yogi who, established in unity, worships Me dwelling in all beings, lives in Me whatever be his mode of life. O Arjuna, he who sees equality in all beings by analogy with himself, whether in pleasure or in pain, is regarded as the highest Yogi.',
    'be': '৬.২৯--৬.৩২ শ্রী অভিনবগুপ্ত বলেছেন: যোগে যুক্ত অন্তঃকরণ ওয়ালা সর্বত্র সমদৃষ্টি যোগী সব ভূতে নিজের আত্মাকে এবং নিজের আত্মায় সব ভূতকে দেখে। যে আমাকে সবেতে দেখে এবং সবকে আমাতে দেখে, তার জন্য আমি অদৃশ্য হই না এবং সে আমার জন্য অদৃশ্য হয় না। যে যোগী একীভাবে স্থিত হয়ে সর্ব ভূতে স্থিত আমাকে ভজে, সে সব প্রকারে বর্তমান থাকতে থাকতেই আমার মধ্যেই বর্তায়। হে অর্জুন! যে নিজের উপমা থেকে সব ভূতে সুখ বা দুঃখকে সমান দেখে, সে পরম যোগী মানা হয়েছে।',
    'ka': '೬.೨೯--೬.೩೨ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಯೋಗಯುಕ್ತಅಂತಃಕರಣವುಳ್ಳ ಸರ್ವತ್ರ ಸಮದೃಷ್ಟಿಯುಳ್ಳ ಯೋಗಿಯು ಸಮಸ್ತ ಭೂತಗಳಲ್ಲಿ ತನ್ನ ಆತ್ಮನನ್ನು ಹಾಗೂ ತನ್ನ ಆತ್ಮನಲ್ಲಿ ಸಮಸ್ತ ಭೂತಗಳನ್ನು ನೋಡುತ್ತಾನೆ. ಯಾರು ನನ್ನನ್ನು ಎಲ್ಲದರಲ್ಲೂ ನೋಡುತ್ತಾನೋ ಹಾಗೂ ಎಲ್ಲವನ್ನೂ ನನ್ನಲ್ಲಿ ನೋಡುತ್ತಾನೋ, ಆತನಿಗೆ ನಾನು ಅದೃಶ್ಯನಾಗುವುದಿಲ್ಲ ಹಾಗೂ ಆತನು ನನಗೆ ಅದೃಶ್ಯನಾಗುವುದಿಲ್ಲ. ಯಾವ ಯೋಗಿಯು ಏಕಿಭಾವದಲ್ಲಿ ಸ್ಥಿತನಾಗಿ ಸಮಸ್ತ ಭೂತಗಳಲ್ಲಿ ನೆಲೆಸಿರುವ ನನ್ನನ್ನು ಭಜಿಸುತ್ತಾನೋ, ಆತನು ಸರ್ವಪ್ರಕಾರಗಳಲ್ಲಿ ವರ್ತಿಸುತ್ತಿದ್ದರೂ ನನ್ನಲ್ಲೇ ವರ್ತಿಸುತ್ತಾನೆ. ಹೇ ಅರ್ಜುನ! ಯಾರು ತನ್ನ ಉಪಮೆಯಿಂದ ಸಮಸ್ತ ಭೂತಗಳಲ್ಲಿ ಸುಖ ಅಥವಾ ದುಃಖಗಳನ್ನು ಸಮವಾಗಿ ನೋಡುತ್ತಾನೋ, ಆತನು ಪರಮಯೋಗಿಯೆಂದು ಪರಿಗಣಿಸಲ್ಪಡುತ್ತಾನೆ'
}

abhinav_35_36 = {
    'hi': '।।6.35--6.36।। श्री अभिनवगुप्त कहते हैं: श्री भगवान् बोले: हे महाबाहो ! इसमें कोई संशय नहीं कि चंचल मन का निग्रह अत्यन्त कठिन है; किन्तु अभ्यास (निरन्तर भगवच्चिन्तन) और वैराग्य (विषय-तृष्णा-त्याग) के द्वारा इसका निग्रह सम्भव है। जिसका मन वश में नहीं है, उसके लिए योग दुष्प्राप्य (कठिन) है; परन्तु वशीकृत मन वाले प्रयत्नशील साधक द्वारा उपायपूर्वक योग सुलभता से सिद्ध किया जा सकता है।',
    'en': '6.35--36 Sri Abhinavagupta states: The Blessed Lord said: Without doubt, O mighty-armed, the restless mind is difficult to restrain; but by constant practice and dispassion it can be brought under control. Yoga is difficult of attainment by one whose mind is uncurbed; but by the self-controlled man who strives, it can be attained by proper means.',
    'be': '৬.৩৫--৬.৩৬ শ্রী অভিনবগুপ্ত বলেছেন: শ্রী ভগবান বললেন: হে মহাবাহো! এতে কোন সং শয় নেই যে চঞ্চল মনের নিগ্রহ অত্যন্ত কঠিন; কিন্তু অভ্যাস (নিরন্তর ভগবচ্চিন্তন) ও বৈরাগ্য (বিষয়-তৃষ্ণা-ত্যাগ) এর দ্বারা এর নিগ্রহ সম্ভব। যার মন বশে নেই, তার জন্য যোগ দুষ্প্রাপ্য (কঠিন); কিন্তু বশীকৃত মন ওয়ালা সচেষ্ট সাধক দ্বারা উপায়পূর্ব ক যোগ সুলভতা থেকে সিদ্ধ করা যেতে পারে।',
    'ka': '೬.೩೫--೬.೩೬ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಶ್ರೀ ಭಗವಂತನು ನುಡಿದನು: ಹೇ ಮಹಾಬಾಹೋ! ಚಂಚಲವಾದ ಮನಸ್ಸಿನ ನಿಗ್ರಹವು ಅತ್ಯಂತ ಕಠಿಣವೆಂಬುದರಲ್ಲಿ ಇನ್ಯಾವ ಸಂಶಯವೂ ಇಲ್ಲ; ಆದರೆ ಅಭ್ಯಾಸ (ನಿರಂತರ ಭಗವಚ್ಚಿಂತನೆ) ಹಾಗೂ ವೈರಾಗ್ಯಗಳ (ವಿಷಯತೃಷ್ಣಾತ್ಯಾಗ) ಮೂಲಕ ಇದರ ನಿಗ್ರಹವು ಸಾಧ್ಯ. ಯಾರ ಮನಸ್ಸು ವಶದಲ್ಲಿಲ್ಲವೋ, ಆತನಿಗೆ ಯೋಗವು ದುಷ್ಪ್ರಾಪ್ಯವಾಗಿದೆ (ಕಠಿಣ); ಆದರೆ ವಶೀಕೃತಮನಸ್ಕನಾದ ಪ್ರಯತ್ನಶೀಲಸಾಧಕನಿಂದ ಉಪಾಯಪೂರ್ವಕವಾಗಿ ಯೋಗವನ್ನು ಸುಲಭವಾಗಿ ಸಿದ್ಧಿಸಿಕೊಳ್ಳಬಹುದು'
}

